const { updateFPS, getFPS } = require('./fps');

function gameLoop() {
  // Your existing game loop code here

  updateFPS();
  document.getElementById('fps').textContent = `${getFPS()} FPS`;
}

// Call gameLoop every frame
setInterval(gameLoop, 1000 / 60);

let lastFrameTime = performance.now();
let frameCount = 0;
let fps = 0;

function updateFPS() {
  frameCount++;
  const currentTime = performance.now();
  const deltaTime = currentTime - lastFrameTime;

  if (deltaTime >= 1000) {
    fps = Math.round((frameCount / (deltaTime / 1000)));
    frameCount = 0;
    lastFrameTime = currentTime;
  }
}

function getFPS() {
  return fps;
}

module.exports = { updateFPS, getFPS };

